mapper.select:
SELECT COUNT(*) > 0
FROM shift_schedule
WHERE store_staff_id = #{storeStaffId}
  AND work_date = #{workDate}
  AND status != 'REJECTED'

      AND shift_id != #{excludeShiftId}

  AND (
      (confirmed_start_at IS NOT NULL AND confirmed_start_at < #{endTime} AND confirmed_end_at > #{startTime})
      OR
      (confirmed_start_at IS NULL AND requested_start_at < #{endTime} AND requested_end_at > #{startTime})
  )

mapper.delete:
DELETE FROM shift_schedule
WHERE shift_id = #{shiftId}
  AND store_staff_id = #{storeStaffId}
  AND status = 'SUBMITTED'

mapper.select:
SELECT s.shift_id, s.store_id, s.store_staff_id, m.name AS staff_name, s.work_date, s.requested_start_at, s.requested_end_at, s.confirmed_start_at, s.confirmed_end_at, s.planned_break_minutes, s.status, s.staff_memo, s.owner_memo FROM shift_schedule s JOIN store_staff ss ON s.store_staff_id = ss.store_staff_id JOIN member m ON ss.member_id = m.member_id WHERE s.store_id = #{storeId} AND s.status = 'SUBMITTED'
AND s.work_date >= #{startDate}
AND s.work_date < #{endDate}
ORDER BY s.work_date ASC, s.requested_start_at ASC

mapper.update:
UPDATE shift_schedule
SET status = #{status},
    owner_memo = #{ownerMemo},
    updated_at = CURRENT_TIMESTAMP
WHERE shift_id = #{shiftId}
  AND store_id = #{storeId}
